package main

import (
	"flag"
	"fmt"
	"os"
)

var version = "a75b67b"
var commit = "a75b67b73b9edb91dfc9f302dd108fa9d3ea5b05"
var builtAt = "2026-04-17 19:59 UTC"
var builtBy = "build.sh"

func printBanner() {
	fmt.Println()
	fmt.Println(` _ __ _____   _(_)__  _____`)
	fmt.Println(`| '__/ _ \ \ / / \ \ / / _ \`)
	fmt.Println(`| | |  __/\ V /| |\ V /  __/`)
	fmt.Println(`|_|  \___| \_/ |_| \_/ \___|`)
	fmt.Println()
}

func main() {
	var (
		configPath    string
		excludeList   multiFlag
		formatter     string
		maxOpenFiles  int
		setExitStatus bool
		showVersion   bool
	)

	flag.StringVar(&configPath, "config", "", "path to the configuration TOML file, defaults to $XDG_CONFIG_HOME/revive.toml or $HOME/revive.toml, if present (i.e. -config myconf.toml)")
	flag.Var(&excludeList, "exclude", "list of globs which specify files to be excluded (i.e. -exclude foo/...)")
	flag.StringVar(&formatter, "formatter", "", "formatter to be used for the output (i.e. -formatter stylish)")
	flag.IntVar(&maxOpenFiles, "max_open_files", 0, "maximum number of open files at the same time")
	flag.BoolVar(&setExitStatus, "set_exit_status", false, "set exit status to 1 if any issues are found, overwrites errorCode and warningCode in config")
	flag.BoolVar(&showVersion, "version", false, "get revive version")

	flag.Usage = func() {
		printBanner()
		fmt.Fprintln(os.Stderr, "Example:")
		fmt.Fprintln(os.Stderr, "  revive -config c.toml -formatter friendly -exclude a.go -exclude b.go ./...")
		fmt.Fprintln(os.Stderr)
		fmt.Fprintf(os.Stderr, "Usage of %s:\n", os.Args[0])
		flag.PrintDefaults()
	}

	flag.Parse()

	if showVersion {
		fmt.Printf("Version:\t%s\nCommit:\t\t%s\nBuilt\t\t%s by %s\n", version, commit, builtAt, builtBy)
		return
	}

	// Load config
	cfg, err := loadConfig(configPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error loading config: %v\n", err)
		os.Exit(2)
	}

	// Get formatter
	if formatter == "" {
		formatter = "default"
	}

	fmtr, err := getFormatter(formatter)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error getting formatter: %v\n", err)
		os.Exit(2)
	}

	// Get files to lint
	args := flag.Args()
	if len(args) == 0 {
		flag.Usage()
		os.Exit(2)
	}

	// Get exclude patterns
	excludes := []string(excludeList)

	// Run linting
	failures, err := lint(args, cfg, excludes, maxOpenFiles)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error linting: %v\n", err)
		os.Exit(2)
	}

	// Format output
	output, hasErrors, hasWarnings, err := fmtr.Format(failures)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error formatting: %v\n", err)
		os.Exit(2)
	}
	_ = hasErrors
	_ = hasWarnings

	if output != "" {
		fmt.Print(output)
	}

	if setExitStatus && len(failures) > 0 {
		os.Exit(1)
	}

	exitCode := 0
	if !setExitStatus {
		if hasErrors && cfg.ErrorCode != 0 {
			exitCode = cfg.ErrorCode
		} else if hasWarnings && cfg.WarningCode != 0 {
			exitCode = cfg.WarningCode
		}
	}
	os.Exit(exitCode)
}
GOEOF

