package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

// Config is the configuration for revive
type Config struct {
	IgnoreGeneratedHeader bool
	Confidence            float64
	Severity              Severity
	Rules                 []RuleConfig
	ErrorCode             int
	WarningCode           int
}

// RuleConfig is the configuration for a rule
type RuleConfig struct {
	Name      string
	Arguments []interface{}
	Severity  Severity
	Disabled  bool
}

// Severity represents the severity of an issue
type Severity string

const (
	SeverityWarning Severity = "warning"
	SeverityError   Severity = "error"
)

// defaultRules contains the default set of rules when no config is provided
var defaultRules = []RuleConfig{
	{Name: "blank-imports"},
	{Name: "context-as-argument"},
	{Name: "context-keys-type"},
	{Name: "dot-imports"},
	{Name: "empty-block"},
	{Name: "error-naming"},
	{Name: "error-return"},
	{Name: "error-strings"},
	{Name: "errorf"},
	{Name: "exported"},
	{Name: "increment-decrement"},
	{Name: "indent-error-flow"},
	{Name: "package-comments"},
	{Name: "range"},
	{Name: "receiver-naming"},
	{Name: "redefines-builtin-id"},
	{Name: "superfluous-else"},
	{Name: "time-naming"},
	{Name: "unexported-return"},
	{Name: "unreachable-code"},
	{Name: "unused-parameter"},
	{Name: "var-declaration"},
	{Name: "var-naming"},
}

func loadConfig(configPath string) (*Config, error) {
	cfg := &Config{
		Confidence: 0.8,
		Severity:   SeverityWarning,
	}

	if configPath == "" {
		// Look for default config locations
		xdgConfigHome := os.Getenv("XDG_CONFIG_HOME")
		if xdgConfigHome != "" {
			p := filepath.Join(xdgConfigHome, "revive.toml")
			if _, err := os.Stat(p); err == nil {
				configPath = p
			}
		}
		if configPath == "" {
			home, err := os.UserHomeDir()
			if err == nil {
				p := filepath.Join(home, "revive.toml")
				if _, err := os.Stat(p); err == nil {
					configPath = p
				}
			}
		}
	}

	if configPath == "" {
		// Use default rules
		cfg.Rules = make([]RuleConfig, len(defaultRules))
		copy(cfg.Rules, defaultRules)
		for i := range cfg.Rules {
			cfg.Rules[i].Severity = SeverityWarning
		}
		return cfg, nil
	}

	// Parse TOML config
	return parseTomlConfig(configPath, cfg)
}

// parseTomlConfig parses a TOML config file
func parseTomlConfig(path string, cfg *Config) (*Config, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("reading config file: %w", err)
	}

	doc, err := parseTOML(string(data))
	if err != nil {
		return nil, fmt.Errorf("parsing config file: %w", err)
	}

	if v, ok := doc["ignoreGeneratedHeader"]; ok {
		if b, ok := v.(bool); ok {
			cfg.IgnoreGeneratedHeader = b
		}
	}
	if v, ok := doc["confidence"]; ok {
		switch n := v.(type) {
		case float64:
			cfg.Confidence = n
		case int64:
			cfg.Confidence = float64(n)
		}
	}
	if v, ok := doc["severity"]; ok {
		if s, ok := v.(string); ok {
			cfg.Severity = Severity(s)
		}
	}
	if v, ok := doc["errorCode"]; ok {
		if n, ok := v.(int64); ok {
			cfg.ErrorCode = int(n)
		}
	}
	if v, ok := doc["warningCode"]; ok {
		if n, ok := v.(int64); ok {
			cfg.WarningCode = int(n)
		}
	}

	// Parse rules
	if rulesMap, ok := doc["rule"]; ok {
		if rm, ok := rulesMap.(map[string]interface{}); ok {
			for ruleName, ruleVal := range rm {
				rc := RuleConfig{
					Name:     ruleName,
					Severity: cfg.Severity,
				}
				if ruleMap, ok := ruleVal.(map[string]interface{}); ok {
					if sev, ok := ruleMap["severity"]; ok {
						if s, ok := sev.(string); ok {
							rc.Severity = Severity(s)
						}
					}
					if dis, ok := ruleMap["Disabled"]; ok {
						if b, ok := dis.(bool); ok {
							rc.Disabled = b
						}
					}
					if args, ok := ruleMap["arguments"]; ok {
						rc.Arguments = toInterfaceSlice(args)
					}
				}
				cfg.Rules = append(cfg.Rules, rc)
			}
		}
	}

	return cfg, nil
}

func toInterfaceSlice(v interface{}) []interface{} {
	switch val := v.(type) {
	case []interface{}:
		return val
	default:
		return []interface{}{v}
	}
}

// Simple TOML parser for the revive config format
// Only supports the features needed by revive

type tomlValue interface{}

func parseTOML(input string) (map[string]interface{}, error) {
	p := &tomlParser{
		input: input,
		doc:   make(map[string]interface{}),
	}
	return p.parse()
}

type tomlParser struct {
	input   string
	pos     int
	doc     map[string]interface{}
	current map[string]interface{}
	section []string
}

func (p *tomlParser) parse() (map[string]interface{}, error) {
	p.current = p.doc
	lines := strings.Split(p.input, "\n")
	i := 0
	for i < len(lines) {
		line := strings.TrimRight(lines[i], "\r")
		trimmed := strings.TrimSpace(line)

		// Skip empty lines and comments
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			i++
			continue
		}

		// Section header
		if strings.HasPrefix(trimmed, "[") && !strings.HasPrefix(trimmed, "[[") {
			sectionName := trimmed[1:strings.Index(trimmed, "]")]
			parts := strings.Split(sectionName, ".")
			p.section = parts
			// Navigate to the section, creating maps as needed
			p.current = p.getOrCreateSection(p.doc, parts)
			i++
			continue
		}

		// Array of tables [[...]]
		if strings.HasPrefix(trimmed, "[[") {
			// Not implemented for now
			i++
			continue
		}

		// Key-value pair
		eqIdx := strings.Index(trimmed, "=")
		if eqIdx < 0 {
			i++
			continue
		}
		key := strings.TrimSpace(trimmed[:eqIdx])
		valStr := strings.TrimSpace(trimmed[eqIdx+1:])

		// Handle multi-line arrays
		if strings.HasPrefix(valStr, "[") && !strings.HasSuffix(strings.TrimRight(valStr, " \t"), "]") {
			// Multi-line array - collect lines until we get closing ]
			fullVal := valStr
			for !isCompleteValue(fullVal) && i+1 < len(lines) {
				i++
				fullVal += "\n" + strings.TrimRight(lines[i], "\r")
			}
			val, err := parseValue(fullVal)
			if err != nil {
				return nil, fmt.Errorf("parsing value for key %s: %w", key, err)
			}
			p.current[key] = val
		} else {
			val, err := parseValue(valStr)
			if err != nil {
				return nil, fmt.Errorf("parsing value for key %s: %w", key, err)
			}
			p.current[key] = val
		}
		i++
	}
	return p.doc, nil
}

func (p *tomlParser) getOrCreateSection(doc map[string]interface{}, parts []string) map[string]interface{} {
	current := doc
	for _, part := range parts {
		if existing, ok := current[part]; ok {
			if m, ok := existing.(map[string]interface{}); ok {
				current = m
			} else {
				// Create a new map
				m := make(map[string]interface{})
				current[part] = m
				current = m
			}
		} else {
			m := make(map[string]interface{})
			current[part] = m
			current = m
		}
	}
	return current
}

func isCompleteValue(s string) bool {
	s = strings.TrimSpace(s)
	if !strings.HasPrefix(s, "[") {
		return true
	}
	depth := 0
	inStr := false
	for _, c := range s {
		switch {
		case c == '"' && !inStr:
			inStr = true
		case c == '"' && inStr:
			inStr = false
		case c == '[' && !inStr:
			depth++
		case c == ']' && !inStr:
			depth--
		}
	}
	return depth == 0
}

func parseValue(s string) (interface{}, error) {
	s = strings.TrimSpace(s)

	// Strip inline comment
	if !strings.HasPrefix(s, "\"") && !strings.HasPrefix(s, "[") {
		if idx := strings.Index(s, " #"); idx >= 0 {
			s = strings.TrimSpace(s[:idx])
		}
		if idx := strings.Index(s, "\t#"); idx >= 0 {
			s = strings.TrimSpace(s[:idx])
