func parseTOML(input string) (map[string]interface{}, error) {
	p := &tomlParser{
		input: input,
		doc:   make(map[string]interface{}),
	}
	return p.parse()
}

type tomlParser struct {
	input   string
	pos     int
	doc     map[string]interface{}
	current map[string]interface{}
	section []string
}

func (p *tomlParser) parse() (map[string]interface{}, error) {
	p.current = p.doc
	lines := strings.Split(p.input, "\n")
	i := 0
	for i < len(lines) {
		line := strings.TrimRight(lines[i], "\r")
		trimmed := strings.TrimSpace(line)

		// Skip empty lines and comments
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			i++
			continue
		}

		// Section header
		if strings.HasPrefix(trimmed, "[") && !strings.HasPrefix(trimmed, "[[") {
			sectionName := trimmed[1:strings.Index(trimmed, "]")]
			parts := strings.Split(sectionName, ".")
			p.section = parts
			// Navigate to the section, creating maps as needed
			p.current = p.getOrCreateSection(p.doc, parts)
			i++
			continue
		}

		// Array of tables [[...]]
		if strings.HasPrefix(trimmed, "[[") {
			// Not implemented for now
			i++
			continue
		}

		// Key-value pair
		eqIdx := strings.Index(trimmed, "=")
		if eqIdx < 0 {
			i++
			continue
		}
		key := strings.TrimSpace(trimmed[:eqIdx])
		valStr := strings.TrimSpace(trimmed[eqIdx+1:])

		// Handle multi-line arrays
		if strings.HasPrefix(valStr, "[") && !strings.HasSuffix(strings.TrimRight(valStr, " \t"), "]") {
			// Multi-line array - collect lines until we get closing ]
			fullVal := valStr
			for !isCompleteValue(fullVal) && i+1 < len(lines) {
				i++
				fullVal += "\n" + strings.TrimRight(lines[i], "\r")
			}
			val, err := parseValue(fullVal)
			if err != nil {
				return nil, fmt.Errorf("parsing value for key %s: %w", key, err)
			}
			p.current[key] = val
		} else {
			val, err := parseValue(valStr)
			if err != nil {
				return nil, fmt.Errorf("parsing value for key %s: %w", key, err)
			}
			p.current[key] = val
		}
		i++
	}
	return p.doc, nil
}

func (p *tomlParser) getOrCreateSection(doc map[string]interface{}, parts []string) map[string]interface{} {
	current := doc
	for _, part := range parts {
		if existing, ok := current[part]; ok {
			if m, ok := existing.(map[string]interface{}); ok {
				current = m
			} else {
				// Create a new map
				m := make(map[string]interface{})
				current[part] = m
				current = m
			}
		} else {
			m := make(map[string]interface{})
			current[part] = m
			current = m
		}
	}
	return current
}

