package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"go/types"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// runLint runs lint on the provided packages/files
func runLint(args []string, cfg *Config, excludes []string, maxOpenFiles int) ([]Failure, error) {
	// Expand file patterns
	files, err := expandArgs(args)
	if err != nil {
		return nil, err
	}

	// Filter out excluded files
	files = filterExcludes(files, excludes)

	if len(files) == 0 {
		return nil, nil
	}

	// Group files by package directory
	pkgGroups := groupByPackage(files)

	var allFailures []Failure

	for _, group := range pkgGroups {
		failures, err := lintPackage(group, cfg)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error linting package: %v\n", err)
			continue
		}
		allFailures = append(allFailures, failures...)
	}

	// Sort failures by file, then line, then column
	sort.Slice(allFailures, func(i, j int) bool {
		pi := allFailures[i].Position.Start
		pj := allFailures[j].Position.Start
		if pi.Filename != pj.Filename {
			return pi.Filename < pj.Filename
		}
		if pi.Line != pj.Line {
			return pi.Line < pj.Line
		}
		return pi.Column < pj.Column
	})

	return allFailures, nil
}

// expandArgs expands file/package arguments to a list of .go files
func expandArgs(args []string) ([]string, error) {
	var files []string
	for _, arg := range args {
		if strings.HasSuffix(arg, "...") {
			// Recursive glob
			dir := strings.TrimSuffix(arg, "/...")
			if dir == "..." {
				dir = "."
			}
			dir = strings.TrimSuffix(dir, "/...")
			err := filepath.WalkDir(dir, func(path string, d os.DirEntry, err error) error {
				if err != nil {
					return nil
				}
				if d.IsDir() {
					// Skip hidden directories
					if strings.HasPrefix(d.Name(), ".") && path != dir {
						return filepath.SkipDir
					}
					return nil
				}
				if strings.HasSuffix(path, ".go") {
					files = append(files, path)
				}
				return nil
			})
			if err != nil {
				return nil, err
			}
		} else if strings.HasSuffix(arg, ".go") {
			// Single Go file
			if _, err := os.Stat(arg); err == nil {
				files = append(files, arg)
			}
		} else {
			// Package directory - find all .go files
			info, err := os.Stat(arg)
			if err != nil {
				// Try as a directory
				return nil, fmt.Errorf("invalid argument: %s", arg)
			}
			if info.IsDir() {
				entries, err := os.ReadDir(arg)
				if err != nil {
					return nil, err
				}
				for _, entry := range entries {
					if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".go") {
						files = append(files, filepath.Join(arg, entry.Name()))
					}
				}
			} else if strings.HasSuffix(arg, ".go") {
				files = append(files, arg)
			}
		}
	}
	return files, nil
}

// filterExcludes filters files matching exclude patterns
func filterExcludes(files []string, excludes []string) []string {
	if len(excludes) == 0 {
		return files
	}
	var result []string
	for _, f := range files {
		excluded := false
		for _, pattern := range excludes {
			if matchExclude(f, pattern) {
				excluded = true
				break
			}
		}
		if !excluded {
			result = append(result, f)
		}
	}
	return result
}

// matchExclude checks if a file matches an exclude pattern
func matchExclude(file, pattern string) bool {
	// Handle ... pattern
	if strings.HasSuffix(pattern, "...") {
		dir := strings.TrimSuffix(pattern, "/...")
		if dir == "..." {
			dir = "."
		}
		// Check if file is in this dir
		dir = filepath.Clean(dir)
		file = filepath.Clean(file)
		return strings.HasPrefix(file, dir+string(os.PathSeparator)) || file == dir
	}

	// Direct match
	if file == pattern {
		return true
	}

	// Glob match
	matched, err := filepath.Match(pattern, file)
	if err == nil && matched {
		return true
	}

	// Try matching just the filename
	_, fname := filepath.Split(file)
	_, pname := filepath.Split(pattern)
	if pname != "" {
		matched, err = filepath.Match(pname, fname)
		if err == nil && matched {
			return true
		}
	}

	return false
}

// groupByPackage groups files by their directory (package)
func groupByPackage(files []string) [][]string {
	dirMap := make(map[string][]string)
	var dirs []string

	for _, f := range files {
		dir := filepath.Dir(f)
		if _, ok := dirMap[dir]; !ok {
			dirs = append(dirs, dir)
		}
		dirMap[dir] = append(dirMap[dir], f)
	}

	sort.Strings(dirs)
	result := make([][]string, 0, len(dirs))
	for _, dir := range dirs {
		result = append(result, dirMap[dir])
	}
	return result
}

// FileContext holds the parsed information about a Go file
type FileContext struct {
	Filename    string
	File        *ast.File
	Fset        *token.FileSet
	TypeInfo    *types.Info
	PackageName string
}

// PackageContext holds all files in a package
type PackageContext struct {
	Files []*FileContext
	Fset  *token.FileSet
	Pkg   *types.Package
}

// lintPackage lints all files in a package
func lintPackage(files []string, cfg *Config) ([]Failure, error) {
	fset := token.NewFileSet()

	var parsedFiles []*ast.File
	var fileContexts []*FileContext

	for _, filename := range files {
		src, err := os.ReadFile(filename)
		if err != nil {
			return nil, fmt.Errorf("reading file %s: %w", filename, err)
		}

		f, err := parser.ParseFile(fset, filename, src, parser.ParseComments)
		if err != nil {
			// Skip files with parse errors
			continue
		}
		parsedFiles = append(parsedFiles, f)
		fc := &FileContext{
			Filename:    filename,
			File:        f,
			Fset:        fset,
			PackageName: f.Name.Name,
		}
		fileContexts = append(fileContexts, fc)
	}

	if len(parsedFiles) == 0 {
		return nil, nil
	}

	// Type checking (best effort)
	conf := types.Config{
		Importer: nil, // simplified importer
		Error:    func(err error) {}, // ignore type errors
