				text = strings.TrimPrefix(text, ":")
				dir.RuleName = strings.TrimSpace(text)
			} else {
				continue
			}

			directives = append(directives, dir)
		}
	}
	return directives
}

// isDisabled checks if a failure at a given position is disabled by directives
func isDisabled(f Failure, ruleName string, directives []Directive) bool {
	line := f.Position.Start.Line

	// Check if disabled by disable-next-line
	for _, d := range directives {
		if d.Type == "disable-next-line" && d.Line == line-1 {
			if d.RuleName == "" || d.RuleName == ruleName {
