			Position: FailurePosition{
				Start: file.Fset.Position(imp.Pos()),
				End:   file.Fset.Position(imp.End()),
			},
			Confidence: 1,
		})
	}

	return failures
}

func isTestFile(filename string) bool {
	return len(filename) > 8 && filename[len(filename)-8:] == "_test.go"
}

func hasJustifyingComment(node ast.Node, file *ast.File, fset *token.FileSet) bool {
	nodePos := fset.Position(node.Pos())
	for _, cg := range file.Comments {
		cgPos := fset.Position(cg.Pos())
		// Comment must be on the same line as or directly before the import
		if cgPos.Line == nodePos.Line || cgPos.Line == nodePos.Line-1 {
			return true
		}
	}
	return false
}
