package main

import (
	"go/ast"
	"go/types"
)

// ContextAsArgumentRule checks that context.Context is the first parameter
type ContextAsArgumentRule struct{}

func (r *ContextAsArgumentRule) Name() string { return "context-as-argument" }

func (r *ContextAsArgumentRule) Apply(file *FileContext, args RuleConfig) []Failure {
	var failures []Failure

	ast.Inspect(file.File, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok {
			return true
		}

		if fn.Type.Params == nil {
			return true
		}

		params := fn.Type.Params.List
		if len(params) == 0 {
			return true
		}

		// Check if any non-first parameter is context.Context
		firstIsContext := false
		for i, param := range params {
			if isContextType(param.Type) {
				if i == 0 {
					firstIsContext = true
					continue
				}
				_ = firstIsContext
				// context.Context is not the first parameter
				failures = append(failures, Failure{
					Failure:    "context.Context should be the first parameter of a function",
					RuleName:   r.Name(),
					Category:   "arg-order",
					Position: FailurePosition{
						Start: file.Fset.Position(param.Pos()),
						End:   file.Fset.Position(param.End()),
					},
					Confidence: 0.9,
				})
			}
		}

		return true
	})

	return failures
}

func isContextType(expr ast.Expr) bool {
	sel, ok := expr.(*ast.SelectorExpr)
	if !ok {
		return false
	}
	ident, ok := sel.X.(*ast.Ident)
	if !ok {
		return false
	}
	return ident.Name == "context" && sel.Sel.Name == "Context"
}

// ContextKeysTypeRule checks that context.WithValue is not called with basic types as keys
type ContextKeysTypeRule struct{}

func (r *ContextKeysTypeRule) Name() string { return "context-keys-type" }

func (r *ContextKeysTypeRule) Apply(file *FileContext, args RuleConfig) []Failure {
	var failures []Failure

	ast.Inspect(file.File, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}

		// Check if it's context.WithValue
		if !isContextWithValue(call) {
			return true
		}

		if len(call.Args) < 2 {
			return true
		}

		// Check if the key (2nd arg) is a basic type
		key := call.Args[1]
		if isBasicTypeKey(key, file) {
			var typeName string
			if file.TypeInfo != nil {
				if tv, ok := file.TypeInfo.Types[key]; ok {
					typeName = tv.Type.String()
				}
			}
			if typeName == "" {
				typeName = basicTypeName(key)
			}

			if typeName != "" {
				failures = append(failures, Failure{
					Failure:    "should not use basic type " + typeName + " as key in context.WithValue",
					RuleName:   r.Name(),
					Category:   "key-type",
					Position: FailurePosition{
						Start: file.Fset.Position(call.Pos()),
						End:   file.Fset.Position(call.End()),
					},
					Confidence: 1,
				})
			}
		}

		return true
	})

	return failures
}

