package main

import (
	"go/ast"
	"go/token"
	"strings"
	"unicode"
)

// ErrorNamingRule checks that error variables are named errFoo or ErrFoo
type ErrorNamingRule struct{}

func (r *ErrorNamingRule) Name() string { return "error-naming" }

func (r *ErrorNamingRule) Apply(file *FileContext, args RuleConfig) []Failure {
	var failures []Failure

	ast.Inspect(file.File, func(n ast.Node) bool {
		decl, ok := n.(*ast.GenDecl)
		if !ok {
			return true
		}

		if decl.Tok != token.VAR {
			return true
		}

		for _, spec := range decl.Specs {
			vs, ok := spec.(*ast.ValueSpec)
			if !ok {
				continue
			}

			for i, name := range vs.Names {
				// Check if the value is of error type
				if !isErrorVar(vs, i, file) {
					continue
				}

				varName := name.Name
				if !hasValidErrorName(varName) {
					failures = append(failures, Failure{
						Failure:    "error var " + varName + " should have name of the form errFoo",
						RuleName:   r.Name(),
						Category:   "naming",
						Position: FailurePosition{
							Start: file.Fset.Position(name.Pos()),
							End:   file.Fset.Position(name.End()),
						},
						Confidence: 0.9,
					})
				}
			}
		}

		return true
	})

	return failures
}

func isErrorVar(vs *ast.ValueSpec, idx int, file *FileContext) bool {
	// Check if type is error
	if vs.Type != nil {
		ident, ok := vs.Type.(*ast.Ident)
		if ok && ident.Name == "error" {
			return true
		}
	}

	// Check if the value implements error interface (by calling errors.New, fmt.Errorf, etc.)
	if idx < len(vs.Values) {
		val := vs.Values[idx]
		return isErrorValue(val)
	}

	return false
}

func isErrorValue(expr ast.Expr) bool {
	call, ok := expr.(*ast.CallExpr)
	if !ok {
		return false
	}

	// Check for errors.New(...)
	if sel, ok := call.Fun.(*ast.SelectorExpr); ok {
		if ident, ok := sel.X.(*ast.Ident); ok {
			if ident.Name == "errors" && sel.Sel.Name == "New" {
				return true
			}
			if ident.Name == "fmt" && sel.Sel.Name == "Errorf" {
				return true
			}
		}
	}

	return false
}

func hasValidErrorName(name string) bool {
	if name == "_" {
		return true
	}
	// Error vars should start with 'err' (unexported) or 'Err' (exported)
	if strings.HasPrefix(name, "err") && len(name) > 3 && unicode.IsUpper(rune(name[3])) {
		return true
	}
	if strings.HasPrefix(name, "Err") && len(name) > 3 {
		return true
	}
	if strings.HasPrefix(name, "err") && len(name) == 3 {
		return true // just "err"
	}
	if strings.HasPrefix(name, "Err") && len(name) == 3 {
		return true // just "Err"
	}
	return false
}

// ErrorReturnRule checks that error is the last return value
type ErrorReturnRule struct{}

func (r *ErrorReturnRule) Name() string { return "error-return" }

func (r *ErrorReturnRule) Apply(file *FileContext, args RuleConfig) []Failure {
	var failures []Failure

	ast.Inspect(file.File, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok {
			return true
		}

		if fn.Type.Results == nil {
			return true
		}

		results := fn.Type.Results.List
		if len(results) < 2 {
			return true
		}

		// Check if any non-last return value is error
		for i, result := range results[:len(results)-1] {
			if isErrorType(result.Type) {
				_ = i
				failures = append(failures, Failure{
					Failure:    "error should be the last type when returning multiple items",
					RuleName:   r.Name(),
					Category:   "arg-order",
					Position: FailurePosition{
						Start: file.Fset.Position(fn.Pos()),
						End:   file.Fset.Position(fn.Type.End()),
					},
					Confidence: 0.9,
				})
				break
			}
		}

		return true
	})

	return failures
}

func isErrorType(expr ast.Expr) bool {
	ident, ok := expr.(*ast.Ident)
	return ok && ident.Name == "error"
}

// ErrorStringsRule checks that error strings are not capitalized or end with punctuation
type ErrorStringsRule struct{}

func (r *ErrorStringsRule) Name() string { return "error-strings" }

func (r *ErrorStringsRule) Apply(file *FileContext, args RuleConfig) []Failure {
	var failures []Failure

	ast.Inspect(file.File, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}

		// Check if it's errors.New() or fmt.Errorf()
		if !isErrorCreation(call) {
			return true
		}

		if len(call.Args) == 0 {
			return true
		}

		// Get the format string
		lit, ok := call.Args[0].(*ast.BasicLit)
		if !ok {
			return true
		}

		str := lit.Value
		if len(str) < 2 {
			return true
		}
		// Remove quotes
		str = str[1 : len(str)-1]
		if str == "" {
			return true
		}

		// Check if it starts with uppercase letter
		firstRune := []rune(str)[0]
		if unicode.IsUpper(firstRune) {
			// Make sure it's not an abbreviation or proper noun (simple check)
			// The rule fires if it starts with a capital letter
			failures = append(failures, Failure{
				Failure:    "error strings should not be capitalized or end with punctuation or a newline",
				RuleName:   r.Name(),
				Category:   "errors",
				Position: FailurePosition{
					Start: file.Fset.Position(lit.Pos()),
					End:   file.Fset.Position(lit.End()),
				},
				Confidence: 0.8,
			})
			return true
		}

		// Check if it ends with punctuation
		lastRune := []rune(str)[len([]rune(str))-1]
		if lastRune == '.' || lastRune == '!' || lastRune == '?' || lastRune == ':' || lastRune == '\n' {
			failures = append(failures, Failure{
				Failure:    "error strings should not be capitalized or end with punctuation or a newline",
				RuleName:   r.Name(),
				Category:   "errors",
				Position: FailurePosition{
					Start: file.Fset.Position(lit.Pos()),
					End:   file.Fset.Position(lit.End()),
				},
				Confidence: 0.8,
			})
		}

		return true
	})

	return failures
}

func isErrorCreation(call *ast.CallExpr) bool {
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return false
	}
	ident, ok := sel.X.(*ast.Ident)
	if !ok {
		return false
	}
	return (ident.Name == "errors" && sel.Sel.Name == "New") ||
		(ident.Name == "fmt" && sel.Sel.Name == "Errorf")
}

// ErrorfRule checks for proper use of fmt.Errorf for error wrapping
type ErrorfRule struct{}

func (r *ErrorfRule) Name() string { return "errorf" }

func (r *ErrorfRule) Apply(file *FileContext, args RuleConfig) []Failure {
	var failures []Failure

	ast.Inspect(file.File, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}

		// Check if it's fmt.Errorf
		if !isFmtErrorf(call) {
			return true
		}

		if len(call.Args) < 2 {
			return true
		}

		// Check format string for %s or %v with error type argument
		fmtLit, ok := call.Args[0].(*ast.BasicLit)
		if !ok {
			return true
		}

		fmtStr := strings.Trim(fmtLit.Value, "\"")

		// Find %v or %s that could be %w
		for i, arg := range call.Args[1:] {
			_ = i
			if !isErrorArg(arg, file) {
				continue
			}

			// Check if corresponding format verb is %s or %v
			verb := getNthVerb(fmtStr, i)
			if verb == "%s" || verb == "%v" {
				failures = append(failures, Failure{
					Failure:    "should replace " + verb + " with %w to propagate errors",
					RuleName:   r.Name(),
					Category:   "errors",
					Position: FailurePosition{
						Start: file.Fset.Position(call.Pos()),
						End:   file.Fset.Position(call.End()),
					},
					Confidence: 0.9,
				})
				break
			}
		}

		return true
	})

	return failures
}

func isFmtErrorf(call *ast.CallExpr) bool {
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return false
	}
	ident, ok := sel.X.(*ast.Ident)
	if !ok {
		return false
	}
	return ident.Name == "fmt" && sel.Sel.Name == "Errorf"
}

func isErrorArg(expr ast.Expr, file *FileContext) bool {
	// Simple check: if the expression is an identifier that looks like an error
	// or a call that returns error
	if file.TypeInfo != nil {
		if tv, ok := file.TypeInfo.Types[expr]; ok {
			if tv.Type != nil && tv.Type.String() == "error" {
				return true
			}
		}
	}
	return false
}

func getNthVerb(fmtStr string, n int) string {
	count := 0
	for i := 0; i < len(fmtStr)-1; i++ {
		if fmtStr[i] == '%' {
			if fmtStr[i+1] == '%' {
				i++ // skip %%
				continue
			}
			if count == n {
				// Find the end of the verb
				j := i + 1
				for j < len(fmtStr) && fmtStr[j] != 'v' && fmtStr[j] != 's' && fmtStr[j] != 'd' &&
					fmtStr[j] != 'f' && fmtStr[j] != 'w' {
					j++
				}
				if j < len(fmtStr) {
					return "%" + string(fmtStr[j])
				}
			}
			count++
		}
	}
	return ""
}
