			if verb == "%s" || verb == "%v" {
				failures = append(failures, Failure{
					Failure:    "should replace " + verb + " with %w to propagate errors",
					RuleName:   r.Name(),
					Category:   "errors",
					Position: FailurePosition{
						Start: file.Fset.Position(call.Pos()),
						End:   file.Fset.Position(call.End()),
					},
					Confidence: 0.9,
				})
				break
			}
		}

		return true
	})

	return failures
}

func isFmtErrorf(call *ast.CallExpr) bool {
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return false
	}
	ident, ok := sel.X.(*ast.Ident)
	if !ok {
		return false
	}
	return ident.Name == "fmt" && sel.Sel.Name == "Errorf"
}

func isErrorArg(expr ast.Expr, file *FileContext) bool {
	// Simple check: if the expression is an identifier that looks like an error
	// or a call that returns error
	if file.TypeInfo != nil {
		if tv, ok := file.TypeInfo.Types[expr]; ok {
			if tv.Type != nil && tv.Type.String() == "error" {
				return true
			}
		}
	}
	return false
}

func getNthVerb(fmtStr string, n int) string {
	count := 0
	for i := 0; i < len(fmtStr)-1; i++ {
		if fmtStr[i] == '%' {
			if fmtStr[i+1] == '%' {
				i++ // skip %%
				continue
			}
			if count == n {
				// Find the end of the verb
				j := i + 1
				for j < len(fmtStr) && fmtStr[j] != 'v' && fmtStr[j] != 's' && fmtStr[j] != 'd' &&
					fmtStr[j] != 'f' && fmtStr[j] != 'w' {
					j++
				}
				if j < len(fmtStr) {
					return "%" + string(fmtStr[j])
				}
			}
			count++
		}
	}
	return ""
}
