package main

import (
	"fmt"
	"go/ast"
	"go/token"
)

// IncrementDecrementRule checks for x += 1 and x -= 1 patterns
type IncrementDecrementRule struct{}

func (r *IncrementDecrementRule) Name() string { return "increment-decrement" }

func (r *IncrementDecrementRule) Apply(file *FileContext, args RuleConfig) []Failure {
	var failures []Failure

	ast.Inspect(file.File, func(n ast.Node) bool {
		assign, ok := n.(*ast.AssignStmt)
		if !ok {
			return true
		}

		if assign.Tok != token.ADD_ASSIGN && assign.Tok != token.SUB_ASSIGN {
			return true
		}

		if len(assign.Rhs) != 1 || len(assign.Lhs) != 1 {
			return true
		}

		rhs, ok := assign.Rhs[0].(*ast.BasicLit)
		if !ok {
			return true
		}

		if rhs.Kind != token.INT || rhs.Value != "1" {
			return true
		}

		// Get the variable name
		lhsStr := exprToString(assign.Lhs[0])

		var msg string
		if assign.Tok == token.ADD_ASSIGN {
			msg = fmt.Sprintf("should replace %s += 1 with %s++", lhsStr, lhsStr)
		} else {
			msg = fmt.Sprintf("should replace %s -= 1 with %s--", lhsStr, lhsStr)
		}

		failures = append(failures, Failure{
			Failure:    msg,
			RuleName:   r.Name(),
			Category:   "style",
			Position: FailurePosition{
				Start: file.Fset.Position(assign.Pos()),
				End:   file.Fset.Position(assign.End()),
			},
			Confidence: 0.8,
		})

		return true
	})

	return failures
}

func exprToString(expr ast.Expr) string {
	switch e := expr.(type) {
	case *ast.Ident:
		return e.Name
	case *ast.SelectorExpr:
		return exprToString(e.X) + "." + e.Sel.Name
	case *ast.IndexExpr:
		return exprToString(e.X) + "[" + exprToString(e.Index) + "]"
	case *ast.StarExpr:
		return "*" + exprToString(e.X)
	case *ast.UnaryExpr:
		return e.Op.String() + exprToString(e.X)
	default:
		return "x"
	}
}
