package main

import (
	"go/ast"
)

// IndentErrorFlowRule checks for unnecessary else blocks after returns/panics
type IndentErrorFlowRule struct{}

func (r *IndentErrorFlowRule) Name() string { return "indent-error-flow" }

func (r *IndentErrorFlowRule) Apply(file *FileContext, args RuleConfig) []Failure {
	return checkSuperfluous(file, args, r.Name())
}

// SuperfluousElseRule checks for unnecessary else blocks
type SuperfluousElseRule struct{}

func (r *SuperfluousElseRule) Name() string { return "superfluous-else" }

func (r *SuperfluousElseRule) Apply(file *FileContext, args RuleConfig) []Failure {
	return checkSuperfluous(file, args, r.Name())
}

func checkSuperfluous(file *FileContext, args RuleConfig, ruleName string) []Failure {
	var failures []Failure

	ast.Inspect(file.File, func(n ast.Node) bool {
		ifStmt, ok := n.(*ast.IfStmt)
		if !ok {
			return true
		}

		if ifStmt.Else == nil {
			return true
		}

		// Check if the if body ends with a return, break, continue, goto, or panic
		if blockTerminates(ifStmt.Body) {
			failures = append(failures, Failure{
				Failure:    "if block ends with a return statement, so drop this else and outdent its block",
				RuleName:   ruleName,
				Category:   "indent",
				Position: FailurePosition{
					Start: file.Fset.Position(ifStmt.Else.Pos()),
					End:   file.Fset.Position(ifStmt.Else.End()),
				},
				Confidence: 0.8,
			})
		}

		return true
	})

	return failures
}

// blockTerminates checks if a block statement always terminates (returns, panics, etc.)
func blockTerminates(block *ast.BlockStmt) bool {
	if block == nil || len(block.List) == 0 {
		return false
	}
	lastStmt := block.List[len(block.List)-1]
	return stmtTerminates(lastStmt)
}

func stmtTerminates(stmt ast.Stmt) bool {
	switch s := stmt.(type) {
	case *ast.ReturnStmt:
		return true
	case *ast.BranchStmt:
		return true // break, continue, goto, fallthrough
	case *ast.ExprStmt:
		// Check for panic()
		call, ok := s.X.(*ast.CallExpr)
		if !ok {
			return false
		}
		ident, ok := call.Fun.(*ast.Ident)
		if !ok {
			return false
		}
		return ident.Name == "panic"
	case *ast.BlockStmt:
		return blockTerminates(s)
	case *ast.IfStmt:
		// If both branches terminate
		if s.Else == nil {
			return false
		}
		return blockTerminates(s.Body) && stmtTerminates(s.Else)
	case *ast.SwitchStmt:
		// Complex - skip for now
		return false
	}
	return false
}
