package main

import (
	"fmt"
	"go/ast"
	"go/token"
)

// RangeRule checks for unnecessary range variables
type RangeRule struct{}

func (r *RangeRule) Name() string { return "range" }

func (r *RangeRule) Apply(file *FileContext, args RuleConfig) []Failure {
	var failures []Failure

	ast.Inspect(file.File, func(n ast.Node) bool {
		rangeStmt, ok := n.(*ast.RangeStmt)
		if !ok {
			return true
		}

		// Check if value (2nd var) is blank identifier
		if rangeStmt.Value == nil {
			return true
		}

		valueIdent, ok := rangeStmt.Value.(*ast.Ident)
		if !ok || valueIdent.Name != "_" {
			return true
		}

		// Check if key (1st var) is also blank - if so, nothing to suggest
		if rangeStmt.Key == nil {
			return true
		}

		// Suggest removing the blank 2nd value
		var keyStr string
		if keyIdent, ok := rangeStmt.Key.(*ast.Ident); ok {
			keyStr = keyIdent.Name
		} else {
			return true
		}

		var msg string
		if rangeStmt.Tok == token.DEFINE {
			msg = fmt.Sprintf("should omit 2nd value from range; this loop is equivalent to `for %s := range ...`", keyStr)
		} else {
