package main

import (
	"go/ast"
	"strings"
	"unicode"
)

// ReceiverNamingRule checks receiver naming conventions
type ReceiverNamingRule struct{}

func (r *ReceiverNamingRule) Name() string { return "receiver-naming" }

func (r *ReceiverNamingRule) Apply(file *FileContext, args RuleConfig) []Failure {
	var failures []Failure

	ast.Inspect(file.File, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok {
			return true
		}

		if fn.Recv == nil || len(fn.Recv.List) == 0 {
			return true
		}

		for _, field := range fn.Recv.List {
			for _, name := range field.Names {
				if name.Name == "_" || name.Name == "" {
					continue
				}
				if isGenericReceiverName(name.Name) {
					failures = append(failures, Failure{
						Failure:    `receiver name should be a reflection of its identity; don't use generic names such as "this" or "self"`,
						RuleName:   r.Name(),
						Category:   "naming",
						Position: FailurePosition{
							Start: file.Fset.Position(fn.Pos()),
							End:   file.Fset.Position(fn.Name.End()),
						},
						Confidence: 0.8,
					})
				}
			}
		}

		return true
	})

	return failures
}

func isGenericReceiverName(name string) bool {
	badNames := []string{"me", "this", "self", "s", "t"}
	for _, bad := range badNames {
		if name == bad {
			return true
		}
	}
	return false
}

// RedefinesBuiltinIdRule checks for redefinition of builtin identifiers
type RedefinesBuiltinIdRule struct{}

func (r *RedefinesBuiltinIdRule) Name() string { return "redefines-builtin-id" }

func (r *RedefinesBuiltinIdRule) Apply(file *FileContext, args RuleConfig) []Failure {
	var failures []Failure

	ast.Inspect(file.File, func(n ast.Node) bool {
		switch decl := n.(type) {
		case *ast.AssignStmt:
			for _, lhs := range decl.Lhs {
				ident, ok := lhs.(*ast.Ident)
				if !ok {
					continue
				}
				if isBuiltin(ident.Name) {
					failures = append(failures, Failure{
						Failure:    "redefines-builtin-id: redefinition of builtin identifier " + ident.Name,
						RuleName:   r.Name(),
						Category:   "naming",
						Position: FailurePosition{
							Start: file.Fset.Position(ident.Pos()),
							End:   file.Fset.Position(ident.End()),
						},
						Confidence: 1,
					})
				}
			}
		case *ast.ValueSpec:
			for _, name := range decl.Names {
				if isBuiltin(name.Name) {
					failures = append(failures, Failure{
						Failure:    "redefines-builtin-id: redefinition of builtin identifier " + name.Name,
						RuleName:   r.Name(),
						Category:   "naming",
						Position: FailurePosition{
							Start: file.Fset.Position(name.Pos()),
							End:   file.Fset.Position(name.End()),
						},
						Confidence: 1,
					})
				}
			}
		case *ast.TypeSpec:
			if isBuiltin(decl.Name.Name) {
				failures = append(failures, Failure{
					Failure:    "redefines-builtin-id: redefinition of builtin identifier " + decl.Name.Name,
					RuleName:   r.Name(),
					Category:   "naming",
					Position: FailurePosition{
						Start: file.Fset.Position(decl.Pos()),
						End:   file.Fset.Position(decl.End()),
					},
					Confidence: 1,
				})
			}
		case *ast.FuncDecl:
			if decl.Recv == nil && isBuiltin(decl.Name.Name) {
				failures = append(failures, Failure{
					Failure:    "redefines-builtin-id: redefinition of builtin identifier " + decl.Name.Name,
					RuleName:   r.Name(),
					Category:   "naming",
					Position: FailurePosition{
						Start: file.Fset.Position(decl.Pos()),
						End:   file.Fset.Position(decl.Name.End()),
					},
					Confidence: 1,
				})
			}
		}
		return true
	})

	return failures
}

var builtinIdentifiers = map[string]bool{
	"append": true, "cap": true, "close": true, "complex": true, "copy": true,
