// TimeNamingRule checks for time.Duration variables with misleading names
type TimeNamingRule struct{}

func (r *TimeNamingRule) Name() string { return "time-naming" }

func (r *TimeNamingRule) Apply(file *FileContext, args RuleConfig) []Failure {
	var failures []Failure

	// Check for variables of type time.Duration with names containing time unit suffixes
	ast.Inspect(file.File, func(n ast.Node) bool {
		// Function parameters
		if fn, ok := n.(*ast.FuncDecl); ok {
			if fn.Type.Params == nil {
				return true
			}
			for _, field := range fn.Type.Params.List {
				if !isTimeDuration(field.Type) {
					continue
				}
				for _, name := range field.Names {
					if hasBadTimeSuffix(name.Name) {
						failures = append(failures, Failure{
							Failure:    "var " + name.Name + " is of type time.Duration; don't use unit-specific suffix " + getBadSuffix(name.Name),
							RuleName:   r.Name(),
							Category:   "time",
							Position: FailurePosition{
								Start: file.Fset.Position(name.Pos()),
								End:   file.Fset.Position(name.End()),
							},
							Confidence: 0.9,
						})
					}
				}
			}
		}

		// Variable declarations
		vs, ok := n.(*ast.ValueSpec)
		if !ok {
			return true
		}

		if !isTimeDuration(vs.Type) {
			return true
		}

		for _, name := range vs.Names {
			if hasBadTimeSuffix(name.Name) {
				failures = append(failures, Failure{
					Failure:    "var " + name.Name + " is of type time.Duration; don't use unit-specific suffix " + getBadSuffix(name.Name),
					RuleName:   r.Name(),
					Category:   "time",
					Position: FailurePosition{
						Start: file.Fset.Position(name.Pos()),
						End:   file.Fset.Position(name.End()),
					},
					Confidence: 0.9,
				})
			}
		}

		return true
	})

	return failures
}

func isTimeDuration(expr ast.Expr) bool {
	if expr == nil {
		return false
	}
	sel, ok := expr.(*ast.SelectorExpr)
	if !ok {
		return false
	}
	ident, ok := sel.X.(*ast.Ident)
	if !ok {
		return false
	}
	return ident.Name == "time" && sel.Sel.Name == "Duration"
}

var badTimeSuffixes = []string{
	"Sec", "Secs", "Second", "Seconds",
	"Min", "Mins", "Minute", "Minutes",
	"Hour", "Hours",
	"Ms", "Millisec", "Millisecond", "Milliseconds",
	"Us", "Microsec", "Microsecond", "Microseconds",
	"Ns", "Nanosec", "Nanosecond", "Nanoseconds",
}

func hasBadTimeSuffix(name string) bool {
	for _, suffix := range badTimeSuffixes {
		if strings.HasSuffix(name, suffix) {
			return true
		}
		// Also check lowercase variants
		lname := strings.ToLower(name)
		lsuffix := strings.ToLower(suffix)
		if strings.HasSuffix(lname, lsuffix) {
			return true
		}
	}
	return false
}

func getBadSuffix(name string) string {
	for _, suffix := range badTimeSuffixes {
		if strings.HasSuffix(name, suffix) {
			return suffix
		}
		lname := strings.ToLower(name)
		lsuffix := strings.ToLower(suffix)
		if strings.HasSuffix(lname, lsuffix) {
			return suffix
		}
	}
	return ""
}

// UnexportedReturnRule checks that exported functions don't return unexported types
type UnexportedReturnRule struct{}

func (r *UnexportedReturnRule) Name() string { return "unexported-return" }

func (r *UnexportedReturnRule) Apply(file *FileContext, args RuleConfig) []Failure {
	var failures []Failure
	pkgName := file.File.Name.Name

	ast.Inspect(file.File, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok {
			return true
		}

		if !ast.IsExported(fn.Name.Name) {
			return true
		}

		if fn.Type.Results == nil {
			return true
		}

		for _, result := range fn.Type.Results.List {
			typeName := getUnexportedTypeName(result.Type)
			if typeName != "" {
				failures = append(failures, Failure{
					Failure:    "exported func " + fn.Name.Name + " returns unexported type " + pkgName + "." + typeName + ", which can be annoying to use",
					RuleName:   r.Name(),
					Category:   "design",
					Position: FailurePosition{
						Start: file.Fset.Position(fn.Type.Pos()),
						End:   file.Fset.Position(fn.Type.End()),
					},
					Confidence: 0.8,
				})
				break
			}
		}

		return true
	})

	return failures
}

func getUnexportedTypeName(expr ast.Expr) string {
	switch e := expr.(type) {
	case *ast.Ident:
		if e.Name != "" && !ast.IsExported(e.Name) && !isBuiltinType(e.Name) {
			return e.Name
		}
	case *ast.StarExpr:
		return getUnexportedTypeName(e.X)
	case *ast.ArrayType:
		return getUnexportedTypeName(e.Elt)
	case *ast.MapType:
		if n := getUnexportedTypeName(e.Key); n != "" {
			return n
		}
		return getUnexportedTypeName(e.Value)
	}
	return ""
}

func isBuiltinType(name string) bool {
	builtinTypes := map[string]bool{
		"bool": true, "byte": true, "complex128": true, "complex64": true,
		"error": true, "float32": true, "float64": true, "int": true,
		"int16": true, "int32": true, "int64": true, "int8": true,
		"rune": true, "string": true, "uint": true, "uint16": true,
		"uint32": true, "uint64": true, "uint8": true, "uintptr": true,
	}
	return builtinTypes[name]
}

// VarNamingRule checks variable naming conventions
type VarNamingRule struct{}

func (r *VarNamingRule) Name() string { return "var-naming" }

func (r *VarNamingRule) Apply(file *FileContext, args RuleConfig) []Failure {
	var failures []Failure

	// Get whitelist/blacklist from arguments
	var whitelist []string
	var blacklist []string

	if len(args.Arguments) >= 1 {
		if wl, ok := args.Arguments[0].([]interface{}); ok {
			for _, w := range wl {
				if s, ok := w.(string); ok {
					whitelist = append(whitelist, s)
				}
			}
		}
	}
	if len(args.Arguments) >= 2 {
		if bl, ok := args.Arguments[1].([]interface{}); ok {
			for _, b := range bl {
				if s, ok := b.(string); ok {
					blacklist = append(blacklist, s)
				}
			}
		}
	}

	// Build the initialism checker with whitelist
	initChecker := newInitialismChecker(whitelist, blacklist)

	checkIdent := func(name, kind string, pos, end interface{ Pos() interface{} }) {
		// Skip blank identifiers
		if name == "_" {
			return
		}

		// Check for underscores
		if strings.Contains(name, "_") {
			suggested := underscoreToCamel(name)
			failures = append(failures, Failure{
				Failure:    "don't use underscores in Go names; " + kind + " " + name + " should be " + suggested,
				RuleName:   r.Name(),
				Category:   "naming",
				Position:   FailurePosition{},
				Confidence: 0.9,
			})
			return
		}

		// Check initialism formatting
		if badName, goodName := initChecker.check(name); badName != "" {
			failures = append(failures, Failure{
				Failure:    kind + " " + badName + " should be " + goodName,
				RuleName:   r.Name(),
				Category:   "naming",
				Position:   FailurePosition{},
				Confidence: 0.8,
			})
		}
	}
	_ = checkIdent

	ast.Inspect(file.File, func(n ast.Node) bool {
		switch decl := n.(type) {
		case *ast.GenDecl:
			for _, spec := range decl.Specs {
				switch s := spec.(type) {
				case *ast.ValueSpec:
					kind := "var"
					if decl.Tok.String() == "const" {
						kind = "const"
					}
					for _, name := range s.Names {
						if name.Name == "_" {
							continue
						}
						checkVarName(name.Name, kind, file, name, &failures, r.Name(), initChecker)
					}
				case *ast.TypeSpec:
					if s.Name.Name == "_" {
						continue
					}
					checkVarName(s.Name.Name, "type", file, s.Name, &failures, r.Name(), initChecker)
				}
			}
		case *ast.FuncDecl:
			if decl.Name.Name != "_" {
				// Check receiver names
				if decl.Recv != nil {
					for _, field := range decl.Recv.List {
						for _, name := range field.Names {
							if name.Name == "_" {
								continue
							}
							checkVarName(name.Name, "receiver", file, name, &failures, r.Name(), initChecker)
						}
					}
				}
				// Check parameter names
				if decl.Type.Params != nil {
					for _, field := range decl.Type.Params.List {
						for _, name := range field.Names {
							if name.Name == "_" {
								continue
							}
							checkVarName(name.Name, "param", file, name, &failures, r.Name(), initChecker)
						}
					}
				}
			}
		case *ast.AssignStmt:
			for _, lhs := range decl.Lhs {
				ident, ok := lhs.(*ast.Ident)
				if !ok || ident.Name == "_" {
					continue
				}
				// Only check := assignments
				// Actually var-naming checks all assignments for short decls
			}
		}
		return true
	})

	return failures
}

func checkVarName(name, kind string, file *FileContext, node *ast.Ident, failures *[]Failure, ruleName string, initChecker *initialismChecker) {
	if name == "_" {
		return
	}

	// Check for underscores
	if strings.Contains(name, "_") {
		// Allow _test package names and test function names
		if strings.HasSuffix(name, "_test") {
			return
		}
		suggested := underscoreToCamel(name)
		*failures = append(*failures, Failure{
			Failure:  "don't use underscores in Go names; " + kind + " " + name + " should be " + suggested,
			RuleName: ruleName,
			Category: "naming",
			Position: FailurePosition{
				Start: file.Fset.Position(node.Pos()),
				End:   file.Fset.Position(node.End()),
			},
			Confidence: 0.9,
		})
		return
	}

	// Check initialism formatting
	if badName, goodName := initChecker.check(name); badName != "" {
		*failures = append(*failures, Failure{
			Failure:  kind + " " + badName + " should be " + goodName,
			RuleName: ruleName,
			Category: "naming",
			Position: FailurePosition{
				Start: file.Fset.Position(node.Pos()),
				End:   file.Fset.Position(node.End()),
			},
			Confidence: 0.8,
		})
	}
}

// underscoreToCamel converts underscore_case to camelCase
func underscoreToCamel(name string) string {
	parts := strings.Split(name, "_")
	if len(parts) == 0 {
		return name
	}
	result := parts[0]
	for _, part := range parts[1:] {
		if part == "" {
			continue
		}
		result += strings.ToUpper(part[:1]) + part[1:]
	}
	return result
}

