						RuleName:   r.Name(),
						Category:   "naming",
						Position: FailurePosition{
							Start: file.Fset.Position(ident.Pos()),
							End:   file.Fset.Position(ident.End()),
						},
						Confidence: 1,
					})
				}
			}
		case *ast.ValueSpec:
			for _, name := range decl.Names {
				if isBuiltin(name.Name) {
					failures = append(failures, Failure{
						Failure:    "redefines-builtin-id: redefinition of builtin identifier " + name.Name,
						RuleName:   r.Name(),
						Category:   "naming",
						Position: FailurePosition{
							Start: file.Fset.Position(name.Pos()),
							End:   file.Fset.Position(name.End()),
						},
						Confidence: 1,
					})
				}
			}
		case *ast.TypeSpec:
			if isBuiltin(decl.Name.Name) {
				failures = append(failures, Failure{
					Failure:    "redefines-builtin-id: redefinition of builtin identifier " + decl.Name.Name,
					RuleName:   r.Name(),
					Category:   "naming",
					Position: FailurePosition{
						Start: file.Fset.Position(decl.Pos()),
						End:   file.Fset.Position(decl.End()),
					},
					Confidence: 1,
				})
			}
		case *ast.FuncDecl:
			if decl.Recv == nil && isBuiltin(decl.Name.Name) {
				failures = append(failures, Failure{
					Failure:    "redefines-builtin-id: redefinition of builtin identifier " + decl.Name.Name,
					RuleName:   r.Name(),
					Category:   "naming",
					Position: FailurePosition{
						Start: file.Fset.Position(decl.Pos()),
						End:   file.Fset.Position(decl.Name.End()),
					},
					Confidence: 1,
				})
			}
		}
		return true
	})

	return failures
}

