package main

import (
	"encoding/json"
	"encoding/xml"
	"fmt"
	"strings"
)

// Formatter formats lint failures for output
type Formatter interface {
	Format(failures []Failure, cfg *Config) (string, error)
}

func getFormatter(name string, cfg *Config) (Formatter, error) {
	switch name {
	case "default", "":
		return &DefaultFormatter{}, nil
	case "json":
		return &JSONFormatter{}, nil
	case "ndjson":
		return &NDJSONFormatter{}, nil
	case "friendly":
		return &FriendlyFormatter{}, nil
	case "stylish":
		return &StylishFormatter{}, nil
	case "checkstyle":
		return &CheckstyleFormatter{}, nil
	case "sarif":
		return &SARIFFormatter{}, nil
	case "plain":
		return &PlainFormatter{}, nil
	case "unix":
		return &UnixFormatter{}, nil
	default:
		return nil, fmt.Errorf("unknown formatter: %s", name)
	}
}

// DefaultFormatter formats like golint
type DefaultFormatter struct{}

func (f *DefaultFormatter) Format(failures []Failure, cfg *Config) (string, error) {
	var sb strings.Builder
	for _, fail := range failures {
		fmt.Fprintf(&sb, "%s:%d:%d: %s\n",
			fail.Position.Start.Filename,
			fail.Position.Start.Line,
			fail.Position.Start.Column,
			fail.Failure)
	}
	return sb.String(), nil
}

// JSONFormatter outputs as JSON array
type JSONFormatter struct{}

type jsonFailure struct {
	Severity        Severity        `json:"Severity"`
	Failure         string          `json:"Failure"`
	RuleName        string          `json:"RuleName"`
	Category        string          `json:"Category"`
	Position        jsonPosition    `json:"Position"`
	Confidence      float64         `json:"Confidence"`
	ReplacementLine string          `json:"ReplacementLine"`
}

type jsonPosition struct {
	Start jsonPos `json:"Start"`
	End   jsonPos `json:"End"`
}

type jsonPos struct {
	Filename string `json:"Filename"`
	Offset   int    `json:"Offset"`
	Line     int    `json:"Line"`
	Column   int    `json:"Column"`
}

func (f *JSONFormatter) Format(failures []Failure, cfg *Config) (string, error) {
	if len(failures) == 0 {
		return "[]\n", nil
	}
	jfailures := make([]jsonFailure, len(failures))
	for i, fail := range failures {
		jfailures[i] = jsonFailure{
			Severity:        fail.Severity,
			Failure:         fail.Failure,
			RuleName:        fail.RuleName,
			Category:        fail.Category,
			Confidence:      fail.Confidence,
			ReplacementLine: fail.ReplacementLine,
			Position: jsonPosition{
				Start: jsonPos{
					Filename: fail.Position.Start.Filename,
					Offset:   fail.Position.Start.Offset,
					Line:     fail.Position.Start.Line,
					Column:   fail.Position.Start.Column,
				},
				End: jsonPos{
					Filename: fail.Position.End.Filename,
					Offset:   fail.Position.End.Offset,
					Line:     fail.Position.End.Line,
					Column:   fail.Position.End.Column,
				},
			},
		}
	}
	data, err := json.Marshal(jfailures)
	if err != nil {
		return "", err
	}
	return string(data) + "\n", nil
}

// NDJSONFormatter outputs newline-delimited JSON
type NDJSONFormatter struct{}

func (f *NDJSONFormatter) Format(failures []Failure, cfg *Config) (string, error) {
	var sb strings.Builder
	for _, fail := range failures {
		jfailure := jsonFailure{
			Severity:        fail.Severity,
			Failure:         fail.Failure,
			RuleName:        fail.RuleName,
			Category:        fail.Category,
			Confidence:      fail.Confidence,
			ReplacementLine: fail.ReplacementLine,
			Position: jsonPosition{
				Start: jsonPos{
					Filename: fail.Position.Start.Filename,
					Offset:   fail.Position.Start.Offset,
					Line:     fail.Position.Start.Line,
					Column:   fail.Position.Start.Column,
				},
				End: jsonPos{
					Filename: fail.Position.End.Filename,
					Offset:   fail.Position.End.Offset,
					Line:     fail.Position.End.Line,
					Column:   fail.Position.End.Column,
				},
			},
		}
		data, err := json.Marshal(jfailure)
		if err != nil {
			return "", err
		}
		sb.Write(data)
		sb.WriteString("\n")
	}
	return sb.String(), nil
}

// FriendlyFormatter outputs human-friendly format
type FriendlyFormatter struct{}

func (f *FriendlyFormatter) Format(failures []Failure, cfg *Config) (string, error) {
	var sb strings.Builder

	errors := 0
	warnings := 0

	// Group by rule name for summary
	warningsByRule := make(map[string]int)
	errorsByRule := make(map[string]int)

	for _, fail := range failures {
		icon := "⚠"
		if fail.Severity == SeverityError {
			icon = "✖"
			errors++
			errorsByRule[fail.RuleName]++
		} else {
			icon = "⚠"
			warnings++
			warningsByRule[fail.RuleName]++
		}

		fmt.Fprintf(&sb, "  %s  https://revive.run/r#%s  %s\n", icon, fail.RuleName, fail.Failure)
		fmt.Fprintf(&sb, "  %s:%d:%d\n", fail.Position.Start.Filename, fail.Position.Start.Line, fail.Position.Start.Column)
		fmt.Fprintln(&sb)
	}

	total := errors + warnings
	if total > 0 {
		symbol := "⚠"
		if errors > 0 {
			symbol = "✖"
		}
		plural := "s"
		if total == 1 {
			plural = ""
		}
