type SARIFFormatter struct{}

type sarifOutput struct {
	Version string     `json:"version"`
	Runs    []sarifRun `json:"runs"`
}

type sarifRun struct {
	Tool    sarifTool     `json:"tool"`
	Results []sarifResult `json:"results,omitempty"`
}

type sarifTool struct {
	Driver sarifDriver `json:"driver"`
}

type sarifDriver struct {
	Name           string      `json:"name"`
	InformationURI string      `json:"informationUri"`
	Rules          []sarifRule `json:"rules"`
}

type sarifRule struct {
	ID         string          `json:"id"`
	HelpURI    string          `json:"helpUri"`
	Properties sarifProperties `json:"properties"`
}

type sarifProperties struct {
	Severity string `json:"severity"`
}

type sarifResult struct {
	RuleID    string           `json:"ruleId"`
	Level     string           `json:"level"`
	Message   sarifMessage     `json:"message"`
	Locations []sarifLocation  `json:"locations"`
}

type sarifMessage struct {
	Text string `json:"text"`
}

type sarifLocation struct {
	PhysicalLocation sarifPhysicalLocation `json:"physicalLocation"`
}

type sarifPhysicalLocation struct {
	ArtifactLocation sarifArtifactLocation `json:"artifactLocation"`
	Region           sarifRegion           `json:"region"`
}

type sarifArtifactLocation struct {
	URI string `json:"uri"`
}

type sarifRegion struct {
	StartLine   int `json:"startLine"`
	StartColumn int `json:"startColumn"`
}

func (f *SARIFFormatter) Format(failures []Failure, cfg *Config) (string, error) {
	// Get rules that were used but didn't produce failures
	triggeredRules := make(map[string]bool)
	for _, fail := range failures {
		triggeredRules[fail.RuleName] = true
	}

	// Find rules that weren't triggered
	var unusedRules []sarifRule
	for _, rule := range cfg.Rules {
		if rule.Disabled {
			continue
		}
		if !triggeredRules[rule.Name] {
			sev := string(rule.Severity)
			if sev == "" {
				sev = "warning"
			}
			unusedRules = append(unusedRules, sarifRule{
				ID:      rule.Name,
				HelpURI: "https://revive.run/r#" + rule.Name,
				Properties: sarifProperties{
					Severity: sev,
				},
			})
		}
	}

	// Limit to one rule in the "rules" section (the original seems to show one)
	var displayRules []sarifRule
	if len(unusedRules) > 0 {
		displayRules = []sarifRule{unusedRules[0]}
	}

	run := sarifRun{
		Tool: sarifTool{
			Driver: sarifDriver{
				Name:           "revive",
				InformationURI: "https://revive.run",
				Rules:          displayRules,
			},
		},
	}

	for _, fail := range failures {
		level := "warning"
		if fail.Severity == SeverityError {
			level = "error"
		}
		run.Results = append(run.Results, sarifResult{
			RuleID: fail.RuleName,
			Level:  level,
			Message: sarifMessage{
				Text: fail.Failure,
			},
			Locations: []sarifLocation{
				{
					PhysicalLocation: sarifPhysicalLocation{
						ArtifactLocation: sarifArtifactLocation{
							URI: fail.Position.Start.Filename,
						},
						Region: sarifRegion{
							StartLine:   fail.Position.Start.Line,
							StartColumn: fail.Position.Start.Column,
						},
					},
				},
			},
		})
	}

	out := sarifOutput{
		Version: "2.1.0",
		Runs:    []sarifRun{run},
	}

	data, err := json.MarshalIndent(out, "", "  ")
	if err != nil {
		return "", err
	}

	return string(data) + "\n", nil
}

