				// e.g., "camelCase" -> split at "C"
				parts = append(parts, string(runes[start:i]))
				start = i
			} else if i+1 < len(runes) && unicode.IsLower(runes[i+1]) {
				// e.g., "HTTPClient" -> split before "C"
				parts = append(parts, string(runes[start:i]))
				start = i
			}
		}
	}

	parts = append(parts, string(runes[start:]))
	return parts
}

// assembleParts assembles parts back into a name
func assembleParts(parts []string, originalName string) string {
	if len(parts) == 0 {
		return ""
	}

	firstRune := rune(originalName[0])
	var sb strings.Builder

	for i, part := range parts {
		if i == 0 {
			if unicode.IsUpper(firstRune) {
				// First character was uppercase - capitalize first part
				if len(part) > 0 {
					sb.WriteString(strings.ToUpper(part[:1]) + part[1:])
				}
			} else {
				// First character was lowercase
				sb.WriteString(part)
			}
		} else {
			// Subsequent parts: capitalize first letter if not an all-caps initialism
			if part == strings.ToUpper(part) && len(part) > 1 {
				sb.WriteString(part)
			} else if len(part) > 0 {
				sb.WriteString(strings.ToUpper(part[:1]) + part[1:])
			}
		}
	}

	return sb.String()
}
