type initialismChecker struct {
	initialisms map[string]bool
}

func newInitialismChecker(whitelist, blacklist []string) *initialismChecker {
	ic := &initialismChecker{
		initialisms: make(map[string]bool),
	}

	if len(whitelist) > 0 {
		// Use only the whitelist (override defaults)
		for _, w := range whitelist {
			ic.initialisms[strings.ToUpper(w)] = true
		}
	} else {
		// Use default common initialisms
		for k, v := range commonInitialisms {
			ic.initialisms[k] = v
		}
	}

	// Apply blacklist
	for _, b := range blacklist {
		delete(ic.initialisms, strings.ToUpper(b))
	}

	return ic
}

func (ic *initialismChecker) check(name string) (bad, good string) {
	if name == "" {
		return "", ""
	}

	// Split camelCase name into parts
	parts := splitCamelCaseParts(name)

	newParts := make([]string, len(parts))
	changed := false

	for i, part := range parts {
		upper := strings.ToUpper(part)
		if ic.initialisms[upper] {
			// This part should be all uppercase
			if part != upper {
				newParts[i] = upper
				changed = true
			} else {
				newParts[i] = part
			}
		} else {
			// Check if this looks like a mangled initialism
			// e.g., "Url" should be "URL" (URL is in initialisms)
			corrected := false
			for init := range ic.initialisms {
				if strings.EqualFold(part, init) && part != init {
					newParts[i] = init
					changed = true
					corrected = true
					break
				}
			}
			if !corrected {
				newParts[i] = part
			}
		}
	}

	if !changed {
		return "", ""
	}

	goodName := assembleParts(newParts, name)
	return name, goodName
}

// splitCamelCaseParts splits a camelCase name into its component parts
func splitCamelCaseParts(name string) []string {
	if name == "" {
		return nil
	}

	runes := []rune(name)
	var parts []string
	start := 0

	for i := 1; i < len(runes); i++ {
		curr := runes[i]
		prev := runes[i-1]

		if unicode.IsUpper(curr) {
			if unicode.IsLower(prev) {
				// e.g., "camelCase" -> split at "C"
				parts = append(parts, string(runes[start:i]))
				start = i
			} else if i+1 < len(runes) && unicode.IsLower(runes[i+1]) {
				// e.g., "HTTPClient" -> split before "C"
				parts = append(parts, string(runes[start:i]))
				start = i
			}
		}
	}

	parts = append(parts, string(runes[start:]))
	return parts
}

// assembleParts assembles parts back into a name
func assembleParts(parts []string, originalName string) string {
	if len(parts) == 0 {
		return ""
	}

	firstRune := rune(originalName[0])
	var sb strings.Builder

	for i, part := range parts {
