						},
						Confidence: 1,
					})
				}
			}
		case *ast.ValueSpec:
			for _, name := range decl.Names {
				if isBuiltin(name.Name) {
					failures = append(failures, Failure{
						Failure:    "redefines-builtin-id: redefinition of builtin identifier " + name.Name,
						RuleName:   r.Name(),
						Category:   "naming",
						Position: FailurePosition{
							Start: file.Fset.Position(name.Pos()),
							End:   file.Fset.Position(name.End()),
						},
						Confidence: 1,
					})
				}
			}
		case *ast.TypeSpec:
			if isBuiltin(decl.Name.Name) {
				failures = append(failures, Failure{
					Failure:    "redefines-builtin-id: redefinition of builtin identifier " + decl.Name.Name,
					RuleName:   r.Name(),
					Category:   "naming",
					Position: FailurePosition{
						Start: file.Fset.Position(decl.Pos()),
						End:   file.Fset.Position(decl.End()),
					},
					Confidence: 1,
				})
			}
		case *ast.FuncDecl:
			if decl.Recv == nil && isBuiltin(decl.Name.Name) {
				failures = append(failures, Failure{
					Failure:    "redefines-builtin-id: redefinition of builtin identifier " + decl.Name.Name,
					RuleName:   r.Name(),
					Category:   "naming",
					Position: FailurePosition{
						Start: file.Fset.Position(decl.Pos()),
						End:   file.Fset.Position(decl.Name.End()),
					},
					Confidence: 1,
				})
			}
		}
		return true
	})

	return failures
}

var builtinIdentifiers = map[string]bool{
	"append": true, "cap": true, "close": true, "complex": true, "copy": true,
	"delete": true, "imag": true, "len": true, "make": true, "new": true,
	"panic": true, "print": true, "println": true, "real": true, "recover": true,
	"bool": true, "byte": true, "complex128": true, "complex64": true,
	"error": true, "float32": true, "float64": true, "int": true,
