package main

import (
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
)

// UnusedParameterRule checks for unused function parameters
type UnusedParameterRule struct{}

func (r *UnusedParameterRule) Name() string { return "unused-parameter" }

func (r *UnusedParameterRule) Apply(file *FileContext, args RuleConfig) []Failure {
	var failures []Failure

	ast.Inspect(file.File, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok {
			return true
		}

		if fn.Body == nil {
			return true
		}

		if fn.Type.Params == nil {
			return true
		}

		// Collect parameter names
		for _, field := range fn.Type.Params.List {
			for _, name := range field.Names {
				if name.Name == "_" {
					continue
				}

				// Check if parameter is used
				if !isParamUsed(name, fn, file) {
					failures = append(failures, Failure{
						Failure:    "parameter '" + name.Name + "' seems to be unused, consider removing or renaming it as _",
						RuleName:   r.Name(),
						Category:   "unused",
						Position: FailurePosition{
							Start: file.Fset.Position(name.Pos()),
							End:   file.Fset.Position(name.End()),
						},
						Confidence: 0.8,
					})
				}
			}
		}

		return true
	})

	return failures
}

func isParamUsed(param *ast.Ident, fn *ast.FuncDecl, file *FileContext) bool {
	// Use type info if available
	if file.TypeInfo != nil {
		if obj, ok := file.TypeInfo.Defs[param]; ok {
			if obj == nil {
				return false
			}
			// Check if the object is used
			for _, use := range file.TypeInfo.Uses {
				if use == obj {
					return true
				}
			}
			return false
		}
	}

	// Fallback: simple AST-based check
	return isIdentUsedInFunc(param.Name, fn.Body)
}

func isIdentUsedInFunc(name string, body *ast.BlockStmt) bool {
	if body == nil {
		return false
	}

	used := false
	ast.Inspect(body, func(n ast.Node) bool {
		if used {
			return false
		}
		ident, ok := n.(*ast.Ident)
		if !ok {
			return true
		}
		if ident.Name == name {
			used = true
			return false
		}
		return true
	})
	return used
}

// VarDeclarationRule checks for unnecessary type declarations in var statements
type VarDeclarationRule struct{}

func (r *VarDeclarationRule) Name() string { return "var-declaration" }

func (r *VarDeclarationRule) Apply(file *FileContext, args RuleConfig) []Failure {
	var failures []Failure

	ast.Inspect(file.File, func(n ast.Node) bool {
		decl, ok := n.(*ast.GenDecl)
		if !ok {
			return true
		}

		if decl.Tok != token.VAR {
			return true
		}

		for _, spec := range decl.Specs {
			vs, ok := spec.(*ast.ValueSpec)
			if !ok {
				continue
			}

			// Only check if type AND values are given
			if vs.Type == nil || len(vs.Values) == 0 {
				continue
			}

			// Only check if all values are provided (same count as names)
			if len(vs.Values) != len(vs.Names) {
				continue
			}

			typeName := typeExprToString(vs.Type)

			for i, name := range vs.Names {
				val := vs.Values[i]

				// Check if value is a bool literal (special case)
				if isBoolLiteral(val) {
					// Bool literals are unambiguously bool -> suggest omitting type
					for range vs.Names {
						failures = append(failures, Failure{
							Failure:    fmt.Sprintf("should omit type %s from declaration of var %s; it will be inferred from the right-hand side", typeName, name.Name),
							RuleName:   r.Name(),
							Category:   "style",
							Position: FailurePosition{
								Start: file.Fset.Position(vs.Type.Pos()),
								End:   file.Fset.Position(vs.Type.End()),
							},
							Confidence: 0.8,
						})
						break
					}
					continue
				}

				// Check if value is a zero value
				if isZeroValue(val) {
					zeroStr := zeroValueString(val)
					failures = append(failures, Failure{
						Failure:    fmt.Sprintf("should drop = %s from declaration of var %s; it is the zero value", zeroStr, name.Name),
						RuleName:   r.Name(),
						Category:   "style",
						Position: FailurePosition{
							Start: file.Fset.Position(val.Pos()),
							End:   file.Fset.Position(val.End()),
						},
						Confidence: 0.8,
					})
					continue
				}

				// Value is not zero -> suggest omitting type
				failures = append(failures, Failure{
					Failure:    fmt.Sprintf("should omit type %s from declaration of var %s; it will be inferred from the right-hand side", typeName, name.Name),
					RuleName:   r.Name(),
					Category:   "style",
					Position: FailurePosition{
						Start: file.Fset.Position(vs.Type.Pos()),
						End:   file.Fset.Position(vs.Type.End()),
					},
					Confidence: 0.8,
				})
			}
		}

		return true
	})

	return failures
}

func isBoolLiteral(expr ast.Expr) bool {
	ident, ok := expr.(*ast.Ident)
	return ok && (ident.Name == "true" || ident.Name == "false")
}

func isZeroValue(expr ast.Expr) bool {
	switch e := expr.(type) {
	case *ast.BasicLit:
		switch e.Kind {
		case token.INT:
			return e.Value == "0"
		case token.FLOAT:
			return e.Value == "0" || e.Value == "0.0"
		case token.STRING:
			return e.Value == `""`
		}
	case *ast.Ident:
		return e.Name == "nil"
	}
	return false
}

func zeroValueString(expr ast.Expr) string {
	switch e := expr.(type) {
	case *ast.BasicLit:
		return e.Value
	case *ast.Ident:
		return e.Name
	}
	return ""
}

func typeExprToString(expr ast.Expr) string {
	switch e := expr.(type) {
	case *ast.Ident:
		return e.Name
	case *ast.SelectorExpr:
		return typeExprToString(e.X) + "." + e.Sel.Name
	case *ast.StarExpr:
		return "*" + typeExprToString(e.X)
	case *ast.ArrayType:
		if e.Len == nil {
			return "[]" + typeExprToString(e.Elt)
		}
		return "[...]" + typeExprToString(e.Elt)
	case *ast.MapType:
		return "map[" + typeExprToString(e.Key) + "]" + typeExprToString(e.Value)
	case *ast.InterfaceType:
		return "interface{}"
	default:
		_ = types.Typ // just to reference types package
		return "?"
	}
}
