			e.name = fail.RuleName
			e.count++
			e.severity = fail.Severity
			ruleMap[fail.RuleName] = e
		}

		var errorRules []ruleEntry
		var warningRules []ruleEntry
		for _, e := range ruleMap {
			if e.severity == SeverityError {
				errorRules = append(errorRules, e)
			} else {
				warningRules = append(warningRules, e)
			}
		}

		// Sort for stable output
		sort.Slice(errorRules, func(i, j int) bool { return errorRules[i].name < errorRules[j].name })
		sort.Slice(warningRules, func(i, j int) bool { return warningRules[i].name < warningRules[j].name })

		if len(errorRules) > 0 {
			fmt.Fprintln(&sb, "Errors:")
			for _, e := range errorRules {
				fmt.Fprintf(&sb, "  %d  %s\n", e.count, e.name)
