func (f *FriendlyFormatter) Format(failures []Failure, cfg *Config) (string, error) {
	var sb strings.Builder

	errors := 0
	warnings := 0

	// Group by rule name for summary
	ruleCount := make(map[string]int)

	for _, fail := range failures {
		icon := "⚠"
		if fail.Severity == SeverityError {
			icon = "✖"
			errors++
		} else {
			icon = "⚠"
			warnings++
		}
		ruleCount[fail.RuleName]++

		fmt.Fprintf(&sb, "  %s  https://revive.run/r#%s  %s\n", icon, fail.RuleName, fail.Failure)
		fmt.Fprintf(&sb, "  %s:%d:%d\n", fail.Position.Start.Filename, fail.Position.Start.Line, fail.Position.Start.Column)
		fmt.Fprintln(&sb)
	}

	total := errors + warnings
	if total > 0 {
		symbol := "⚠"
		if errors > 0 {
			symbol = "✖"
		}
		plural := "s"
		if total == 1 {
			plural = ""
		}
		fmt.Fprintf(&sb, "%s %d problem%s (%d error%s, %d warning%s)\n\n",
			symbol, total, plural,
			errors, pluralS(errors), warnings, pluralS(warnings))

		// Sort rule names for consistent output
		// Build separate error and warning rule summaries
		type ruleEntry struct {
			name     string
			count    int
			severity Severity
		}

		ruleMap := make(map[string]ruleEntry)
		for _, fail := range failures {
			e := ruleMap[fail.RuleName]
			e.name = fail.RuleName
			e.count++
			e.severity = fail.Severity
			ruleMap[fail.RuleName] = e
		}

		var errorRules []ruleEntry
		var warningRules []ruleEntry
		for _, e := range ruleMap {
			if e.severity == SeverityError {
				errorRules = append(errorRules, e)
			} else {
				warningRules = append(warningRules, e)
			}
		}

		// Sort for stable output
		sort.Slice(errorRules, func(i, j int) bool { return errorRules[i].name < errorRules[j].name })
		sort.Slice(warningRules, func(i, j int) bool { return warningRules[i].name < warningRules[j].name })

		if len(errorRules) > 0 {
			fmt.Fprintln(&sb, "Errors:")
			for _, e := range errorRules {
				fmt.Fprintf(&sb, "  %d  %s\n", e.count, e.name)
			}
			fmt.Fprintln(&sb)
		}

		if len(warningRules) > 0 {
			fmt.Fprintln(&sb, "Warnings:")
			for _, e := range warningRules {
				fmt.Fprintf(&sb, "  %d  %s\n", e.count, e.name)
			}
			fmt.Fprintln(&sb)
		}
	}

	return sb.String(), nil
}

