// wellKnownInterfaceMethods lists methods from well-known Go interfaces
var wellKnownInterfaceMethods = map[string]bool{
	"Error":    true, // error interface
	"String":   true, // fmt.Stringer
	"Format":   true, // fmt.Formatter
	"MarshalJSON": true,
	"UnmarshalJSON": true,
	"MarshalText": true,
	"UnmarshalText": true,
	"MarshalBinary": true,
	"UnmarshalBinary": true,
	"MarshalXML": true,
	"UnmarshalXML": true,
	"Scan":     true, // sql.Scanner
	"Value":    true, // driver.Valuer
	"Close":    true, // io.Closer
	"Read":     true, // io.Reader
	"Write":    true, // io.Writer
	"Seek":     true, // io.Seeker
	"ReadFrom": true, // io.ReaderFrom
	"WriteTo":  true, // io.WriterTo
	"ServeHTTP": true, // http.Handler
	"Len":      true, // sort.Interface
	"Less":     true, // sort.Interface
	"Swap":     true, // sort.Interface
}

func isWellKnownInterfaceMethod(name string) bool {
	return wellKnownInterfaceMethods[name]
}

func getReceiverTypeName(recv *ast.FieldList) string {
	if recv == nil || len(recv.List) == 0 {
		return ""
	}
	field := recv.List[0]
	return getTypeIdent(field.Type)
}

func getTypeIdent(expr ast.Expr) string {
	switch e := expr.(type) {
	case *ast.Ident:
		return e.Name
	case *ast.StarExpr:
		return getTypeIdent(e.X)
	}
	return ""
}
GOEOF
