# The issue is that package-comments should be package-aware
# When checking if a package has comments, we need to check all files in the package
# 
# The solution: pass extra context to the rule about other files in the package

# Actually the simplest solution: when linting a package group, collect all doc comments
# Then only apply package-comments rule if NO file in the group has a doc comment

# Let me update the lint.go to pass package-level context

cat > /workspace/revive/rules_package.go << 'GOEOF'
package main

import (
	"strings"
)

// PackageCommentsRule checks that packages have comments
type PackageCommentsRule struct{}

func (r *PackageCommentsRule) Name() string { return "package-comments" }

func (r *PackageCommentsRule) Apply(file *FileContext, args RuleConfig) []Failure {
	var failures []Failure

	pkgDecl := file.File.Name

	// Check if there's a package comment on this file
	if file.File.Doc == nil {
		// No package comment - but maybe another file in the package has one
		// This is checked at the package level, but the failure is reported per file
		// We'll report the failure here and let the caller filter based on package context
		failures = append(failures, Failure{
			Failure:    "should have a package comment",
			RuleName:   r.Name(),
			Category:   "comments",
			Position: FailurePosition{
				Start: file.Fset.Position(file.File.Package),
				End:   file.Fset.Position(pkgDecl.End()),
			},
			Confidence: 1,
		})
		return failures
	}

	// Check comment format: "Package pkgname ..."
	doc := strings.TrimSpace(file.File.Doc.Text())
	pkgName := file.File.Name.Name

	if !strings.HasPrefix(strings.ToLower(doc), "package "+strings.ToLower(pkgName)) {
		_ = doc
		_ = pkgName
	}

	return failures
}
GOEOF
echo "rules_package.go updated"

