				return true
			}
		}
	}
	return false
}'''

new_func = '''func isErrorArg(expr ast.Expr, file *FileContext) bool {
	// Use type info if available
	if file.TypeInfo != nil {
		if tv, ok := file.TypeInfo.Types[expr]; ok {
			if tv.Type != nil && tv.Type.String() == "error" {
				return true
			}
		}
	}

	// Fallback: check if the expression is an identifier declared as error type
	if ident, ok := expr.(*ast.Ident); ok {
		return isIdentDeclaredAsError(ident.Name, file)
	}

	return false
}

func isIdentDeclaredAsError(name string, file *FileContext) bool {
	// Look for parameter declarations with error type
	var found bool
	ast.Inspect(file.File, func(n ast.Node) bool {
		if found {
			return false
		}
		fn, ok := n.(*ast.FuncDecl)
		if !ok {
			return true
		}
		if fn.Type.Params == nil {
			return true
		}
		for _, field := range fn.Type.Params.List {
			if !isErrorType(field.Type) {
				continue
			}
			for _, pname := range field.Names {
				if pname.Name == name {
					found = true
					return false
				}
			}
		}
		return true
	})
	return found
}'''

if old_func in content:
    content = content.replace(old_func, new_func)
    with open('/workspace/revive/rules_errors.go', 'w') as f:
        f.write(content)
    print("Replaced successfully")
else:
    print("Not found!")
    idx = content.find("func isErrorArg")
    if idx >= 0:
        print(repr(content[idx:idx+300]))
